private object L10nIndex19 {
    fun fill(m: HashMap<String, Int>) {
        m["In azienda il TFR si rivaluta ogni anno dell'1,5% più il 75% dell'inflazione, con un'imposta sostitutiva sulla rivalutazione. Il confronto usa un'inflazione costante e non include le tasse all'uscita (diverse nei due casi). Regole da validare con un professionista."] = R.string.under_italian_rules_company_held_tfr_is_4b1aca
        m["Le minusvalenze di un anno si possono usare fino al 31 dicembre del quarto anno dopo, per non pagare tasse sulle plusvalenze di azioni, obbligazioni ed ETC (non sui guadagni degli ETF). Gli importi sono portati all'aliquota del 26%."] = R.string.under_italian_rules_losses_can_offset_ga_b6b416
        m["Sono redditi di capitale: tassati per intero, non si compensano con lo zaino."] = R.string.under_italian_rules_these_are_investment_408dee
        m["Con la regola fissa le tre linee coincidono; con le altre si aprono a ventaglio."] = R.string.under_the_fixed_rule_the_three_lines_coi_74eb79
        m["Sui guadagni non ancora incassati pagheresti un'imposta (in genere 26%, 12,5% sui titoli di Stato) solo vendendo. Qui è la stima di quanto sarebbe se vendessi tutto oggi."] = R.string.under_the_italian_model_unrealised_gains_ae1e4b
